import{_ as t,o as a,c as r,a6 as i}from"./chunks/framework.Dtv7txdI.js";const p=JSON.parse('{"title":"Report Security Issues","description":"","frontmatter":{},"headers":[],"relativePath":"v1/report-security-issues.md","filePath":"v1/report-security-issues.md","lastUpdated":1787648967000}'),o={name:"v1/report-security-issues.md"};function s(n,e,l,c,h,d){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="report-security-issues" tabindex="-1">Report Security Issues <a class="header-anchor" href="#report-security-issues" aria-label="Permalink to “Report Security Issues”">​</a></h1><h2 id="how-to-report" tabindex="-1">How to report <a class="header-anchor" href="#how-to-report" aria-label="Permalink to “How to report”">​</a></h2><p>Please <strong>do not open a public issue</strong> for a security vulnerability.</p><p>Open a <a href="https://github.com/joseluisq/nitr/security/advisories/new" target="_blank" rel="noreferrer">private security advisory</a> on the repository instead. That gives us a private channel to confirm the issue, prepare a fix and coordinate disclosure.</p><h2 id="what-makes-a-report-actionable" tabindex="-1">What makes a report actionable <a class="header-anchor" href="#what-makes-a-report-actionable" aria-label="Permalink to “What makes a report actionable”">​</a></h2><ul><li><strong>What the boundary is.</strong> Nitr&#39;s <a href="./server/security#what-the-sandbox-does-not-defend-against">threat model</a> is explicit about what the sandbox does and does not defend against — a report that crosses a documented boundary (a malicious Rust extension module, for example) is a design question rather than a vulnerability.</li><li><strong>A reproducer.</strong> The smallest <code>nitr.toml</code> + Lua script that shows the behaviour. <code>nitr check --print-config</code> output helps when configuration layering is involved.</li><li><strong>The version and how it was built.</strong> <code>nitr --version</code>, plus whether it came from <code>cargo install</code>, a clone, or a distro package, and which Cargo features were enabled.</li><li><strong>The structured log line</strong>, if the issue produces one — <code>[log] format = &quot;json&quot;</code> gives fields rather than prose.</li></ul><h2 id="in-scope" tabindex="-1">In scope <a class="header-anchor" href="#in-scope" aria-label="Permalink to “In scope”">​</a></h2><p>Anything that breaks a boundary the <a href="./server/security">security page</a> claims:</p><ul><li>escaping the Lua sandbox — filesystem, process or network access that the configured policy should have denied;</li><li>bypassing the execution budget or the per-state memory limit;</li><li>SSRF past the <code>nitr.fetch</code> policy, including via DNS rebinding or a redirect hop;</li><li>path traversal out of a static mount or out of <code>nitr.path.normalize</code>;</li><li>forging a signed cookie, session or JWT; timing oracles in verification;</li><li>data leaking between pooled Lua states;</li><li>a request that can crash the process rather than being contained at the request boundary.</li></ul><p>A <code>kind = &quot;panic&quot;</code> error is always worth reporting, even when it looks harmless: panic containment is a last-resort safety net for genuine bugs, not something an application should be able to trigger.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to “Out of scope”">​</a></h2><ul><li>Denial of service by a legitimate client within the configured limits — that is what <code>[limits]</code> and <code>[rate_limit]</code> are for. Tune them.</li><li>The known-weaker items Nitr documents rather than hides: the fixed-window rate limiter&#39;s boundary burst, the inability to invalidate a stateless session server-side, and the absence of a metrics endpoint. See <a href="./server/security#known-weaknesses">Known weaknesses</a>.</li><li>Vulnerabilities in Lua 5.4 or mlua themselves — report those upstream; we will pick up the fix.</li></ul>',12)])])}const m=t(o,[["render",s]]);export{p as __pageData,m as default};
